/**
 * Markdown, rendered through the vocabulary (`design/components/markdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import { MarkdownBody, type MarkdownBodyProps } from './MarkdownBody'
import { Skeleton, type SkeletonProps } from '../structure/Skeleton'
import type { CitationSource } from './SourceList'

export type MarkdownSize = NonNullable<MarkdownProps['size']>

/** Markdown, rendered through the vocabulary: the inputs it takes, by the React member's prop names. */
export interface MarkdownProps {
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The reply's sources in numbered order, which turn each `[n]` in the prose into a Citation to
   * the nth source (without them, `[n]` stays text).
   */
  sources?: CitationSource[]
  /**
   * Whether more is coming, which renders unfinished constructs as text and shows a caret at the
   * end.
   */
  streaming?: boolean
}

/** Markdown, rendered through the vocabulary. */
@Component({
  selector: 'pm-markdown',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotTemplate, MarkdownBody, Skeleton],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- root -->
<div
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-state]="e3()"
[attr.data-pending]="e4()"
[attr.aria-busy]="e5()"
data-member="markdown"
>@if (e6()) {<pm-skeleton
shape="text"
[textStep]="e7()"
[width]="e8()"
></pm-skeleton>} @else {<pm-markdown-body
[source]="e9()"
[size]="e10()"
[sources]="e11()"
[streaming]="e12()"
></pm-markdown-body>}</div>`,
})
export class Markdown {
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  readonly size = input<Exclude<MarkdownProps['size'], undefined>, MarkdownProps['size']>('md', {
    transform: (value: MarkdownProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * The reply's sources in numbered order, which turn each `[n]` in the prose into a Citation to
   * the nth source (without them, `[n]` stays text).
   */
  readonly sources = input<Exclude<MarkdownProps['sources'], undefined>, MarkdownProps['sources']>(
    (() => [])(),
    {
      transform: (value: MarkdownProps['sources']) => (value === undefined ? (() => [])() : value),
    },
  )
  /**
   * Whether more is coming, which renders unfinished constructs as text and shows a caret at the
   * end.
   */
  readonly streaming = input<
    Exclude<MarkdownProps['streaming'], undefined>,
    MarkdownProps['streaming']
  >(false, {
    transform: (value: MarkdownProps['streaming']) => (value === undefined ? false : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: {
      size: () => this.size(),
      sources: () => this.sources(),
      streaming: () => this.streaming(),
    },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.$p.streaming ? 'streaming' : undefined
  }

  protected e4() {
    return this.$p.streaming && this.$.text('default').trim() === '' ? '' : undefined
  }

  protected e5() {
    return this.$p.streaming ? true : undefined
  }

  protected e6() {
    return this.$p.streaming && this.$.text('default').trim() === ''
  }

  protected e7(): SkeletonProps['textStep'] {
    if (!(this.$p.streaming && this.$.text('default').trim() === '')) return undefined as never
    return this.$p.size
  }

  protected e8(): SkeletonProps['width'] {
    if (!(this.$p.streaming && this.$.text('default').trim() === '')) return undefined as never
    return 9
  }

  protected e9(): MarkdownBodyProps['source'] {
    if (this.$p.streaming && this.$.text('default').trim() === '') return undefined as never
    return this.$.text('default')
  }

  protected e10(): MarkdownBodyProps['size'] {
    if (this.$p.streaming && this.$.text('default').trim() === '') return undefined as never
    return this.$p.size
  }

  protected e11(): MarkdownBodyProps['sources'] {
    if (this.$p.streaming && this.$.text('default').trim() === '') return undefined as never
    return this.$p.sources
  }

  protected e12(): MarkdownBodyProps['streaming'] {
    if (this.$p.streaming && this.$.text('default').trim() === '') return undefined as never
    return this.$p.streaming
  }
}
